import re
from datetime import datetime

_DIGITS = "0123456789"
_ANGLE_RE = re.compile(r"<([^<>]*)>")
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_ZIP_PLUS4_RE = re.compile(r"([0-9]+)-([0-9]{4})")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}


def _field(row, key):
    value = row.get(key)
    return "" if value is None else str(value)


def _normalize_email(raw):
    """Return the normalized email if valid, otherwise ""."""
    text = raw
    match = _ANGLE_RE.search(text)
    if match:
        text = match.group(1)
    text = text.strip().lower()

    if text.count("@") == 1:
        local, domain = text.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            text = local + "@gmail.com"

    if text.count("@") != 1:
        return ""
    local, domain = text.split("@")
    if local and "." in domain and not domain.startswith(".") and not domain.endswith("."):
        return text
    return ""


def _normalize_phone(raw):
    """Return the 10-digit normalized phone if valid, otherwise ""."""
    text = raw.lower()
    markers = [pos for pos in (text.find("x"), text.find("ext"), text.find("#")) if pos >= 0]
    if markers:
        text = text[:min(markers)]
    digits = "".join(c for c in text if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    text = raw.strip()
    match = _ZIP_PLUS4_RE.fullmatch(text)
    if match:
        text = match.group(1)
    if len(text) == 4 and all(c in _DIGITS for c in text):
        text = "0" + text
    if len(text) == 5 and all(c in _DIGITS for c in text):
        return text
    return ""


def _normalize_name(raw):
    text = raw.strip()
    if text.isupper() or text.islower():
        text = text.title()
    return text


def _parse_updated(raw):
    text = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            continue
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _normalize_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw) if t.strip()}


def _pick(members, field):
    """Choose the value for `field` from the group's rows.

    Candidates are rows where the normalized field is non-empty. Manual-source
    rows are preferred; then the latest `updated`; ties go to the earlier row
    (members are kept in input order and max() returns the first maximum).
    """
    candidates = [r for r in members if r[field]]
    if not candidates:
        return ""
    manual = [r for r in candidates if r["source"] == "manual"]
    pool = manual or candidates
    return max(pool, key=lambda r: r["updated"])[field]


def _merge(members):
    return {
        "first_name": _pick(members, "first_name"),
        "last_name": _pick(members, "last_name"),
        "zip": _pick(members, "zip"),
        "email": _pick(members, "email"),
        "phone": _pick(members, "phone"),
        "source": _pick(members, "source"),
        "tags": ";".join(sorted(set().union(*(r["tags"] for r in members)))),
        "opted_out": "Y" if any(r["opted_out"] for r in members) else "N",
        "updated": max(r["updated"] for r in members).strftime("%Y-%m-%d"),
    }


def dedupe_contacts(rows):
    """Deduplicate CRM contact rows into one dict per person.

    Output order follows each person's earliest row in the input.
    Rows lacking a valid email and a valid phone are dropped.
    """
    records = []
    for index, row in enumerate(rows):
        records.append({
            "index": index,
            "first_name": _normalize_name(_field(row, "first_name")),
            "last_name": _normalize_name(_field(row, "last_name")),
            "zip": _normalize_zip(_field(row, "zip")),
            "email": _normalize_email(_field(row, "email")),
            "phone": _normalize_phone(_field(row, "phone")),
            "source": _field(row, "source").strip().lower(),
            "tags": _normalize_tags(_field(row, "tags")),
            "opted_out": _field(row, "opted_out").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(_field(row, "updated")),
        })

    valid = [r for r in records if r["email"] or r["phone"]]

    # Union-find over row indexes.
    parent = {r["index"]: r["index"] for r in valid}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    # Link each row to the first row sharing its email, or its (phone, last name) key.
    # This yields the same connected components as comparing every pair.
    email_first = {}
    phone_first = {}
    for r in valid:
        i = r["index"]
        if r["email"]:
            if r["email"] in email_first:
                union(i, email_first[r["email"]])
            else:
                email_first[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].lower())
            if key in phone_first:
                union(i, phone_first[key])
            else:
                phone_first[key] = i

    # Group rows; dict insertion order follows each group's earliest row.
    groups = {}
    for r in valid:
        groups.setdefault(find(r["index"]), []).append(r)

    return [_merge(members) for members in groups.values()]
```

Notes:

- **Opt-outs:** The function doesn't remove opted-out people. It sets `opted_out` to "Y" for any person whose group contains an opted-out row. Filter out `opted_out == "Y"` before the send. Because a single opted-out row flags the whole merged person, a duplicate with an opt-out is excluded entirely, which is the safe result.
- **ZIP+4:** I accept any `digits-4digits` form, not just 5-digit ZIPs, so an Excel-mangled `2139-4307` becomes `02139`.
- **Phone extensions:** The cut uses the earliest of "x", "ext", or "#", so "555-123-4567 ext. 89" and "555-123-4567 #89" both work.
- **Bad dates:** An `updated` value in none of the three formats raises `ValueError` with the offending value. I chose to fail loudly rather than guess the order. Since the spec says these formats are guaranteed, this should only happen if the export changes.
- **Matching:** Matching uses dictionary lookups plus union-find instead of comparing every pair, so it stays fast on large exports.
